/(3)","description":"B_RBF,zu — mittlere jährliche Zulauffracht (AFS63) zum Retentionsbodenfilterbecken.","consumer_worksheets":["A178-10"]},{"ws_code":"A178-09","section_code":"C","symbol":"B_RBFA_zu","label_de":"Mittl. jährl. Zulauffracht RBFA","label_en":"Mean annual load to RBFA","data_type":"number","unit":"kg/a","is_required":true,"enum_values":null,"validation_rules":{"raw":"> 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (8)","description":"B_RBFA,zu — mittlere jährliche Zulauffracht (AFS63) zur Retentionsbodenfilteranlage.","consumer_worksheets":["A178-12"]},{"ws_code":"A178-14","section_code":"C","symbol":"B_RBFA_ab","label_de":"Mittl. jährl. Frachtaustrag RBFA","label_en":"Mean annual load discharge from RBFA","data_type":"number","unit":"kg/a","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (11)","description":"B_RBFA,ab — mittlerer jährlicher Frachtaustrag (AFS63) aus der Retentionsbodenfilteranlage.","consumer_worksheets":["A178-16"]},{"ws_code":"A178-14","section_code":"C","symbol":"B_RBF_ab","label_de":"Mittl. jährl. Frachtaustrag RBF","label_en":"Mean annual load discharge from RBF","data_type":"number","unit":"kg/a","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (13)","description":"B_RBF,ab — mittlerer jährlicher Frachtaustrag (AFS63) aus dem Retentionsbodenfilterbecken.","consumer_worksheets":["A178-15"]},{"ws_code":"A178-14","section_code":"C","symbol":"B_VS","label_de":"Frachtaustrag Vorstufe","label_en":"Load discharge from pre-stage","data_type":"number","unit":"kg/a","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (11)","description":"B_VS — mittlerer jährlicher Frachtaustrag (AFS63) aus der Vorstufe.","consumer_worksheets":["A178-14"]},{"ws_code":"A178-14","section_code":"C","symbol":"B_Dr_RBF","label_de":"Frachtaustrag Filterablauf","label_en":"Load discharge via filter outlet","data_type":"number","unit":"kg/a","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (11)","description":"B_Dr,RBF — mittlerer jährlicher Frachtaustrag (AFS63) über den Filterablauf.","consumer_worksheets":["A178-14"]},{"ws_code":"A178-14","section_code":"C","symbol":"B_FU","label_de":"Frachtaustrag Filterbeckenüberlauf","label_en":"Load discharge via filter overflow","data_type":"number","unit":"kg/a","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (11)","description":"B_FÜ — mittlerer jährlicher Frachtaustrag (AFS63) über den Filterbeckenüberlauf.","consumer_worksheets":["A178-14"]},{"ws_code":"A178-14","section_code":"C","symbol":"B_RRL","label_de":"Frachtaustrag RRL","label_en":"Load discharge via RRL","data_type":"number","unit":"kg/a","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (11)","description":"B_RRL — mittlerer jährlicher Frachtaustrag (AFS63) über den Ablauf einer Regenrückhaltelamelle.","consumer_worksheets":["A178-14"]},{"ws_code":"A178-12","section_code":"C","symbol":"C_RBFA_zu","label_de":"Konzentration im Zulauf RBFA","label_en":"Inflow concentration to RBFA","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"> 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (8)","description":"C_RBFA,zu — mittlere rechnerische Konzentration (AFS63) im Zulauf zur Retentionsbodenfilteranlage.","consumer_worksheets":["A178-13"]},{"ws_code":"A178-12","section_code":"C","symbol":"C_RBF_zu","label_de":"Konzentration im Zulauf RBF","label_en":"Inflow concentration to RBF","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"> 0"},"clause_reference":"§3.2, §6.2.2.3, Gl. (13)","description":"C_RBF,zu — mittlere rechnerische Konzentration (AFS63) im Zulauf zum Retentionsbodenfilterbecken (Abminderung wenn η_VS > 0).","consumer_worksheets":["A178-15"]},{"ws_code":"A178-13","section_code":"B","symbol":"eta_VS","label_de":"Frachtrückhaltegrad Vorstufe","label_en":"Pre-stage load retention efficiency","data_type":"number","unit":"-","is_required":true,"enum_values":null,"validation_rules":{"raw":"0 oder 0,2 (vorhandene RKB / RÜB-DB)"},"clause_reference":"§3.2, §6.2.2.3, Tabelle 1","description":"η_VS — mittlerer jährlicher AFS63-Frachtrückhalt der Vorstufe der RBFA. Default 0; bei vorhandenen RKB (q_A ≤ 10 m/h) oder RÜB-DB: 0,2.","consumer_worksheets":["A178-13"]},{"ws_code":"A178-15","section_code":"C","symbol":"eta_F","label_de":"Frachtrückhaltegrad Filtration","label_en":"Filtration load retention efficiency","data_type":"number","unit":"-","is_required":true,"enum_values":null,"validation_rules":{"raw":"Rechenwert 0,95"},"clause_reference":"§3.2, §6.2.2.3, Tabelle 1, Gl. (13)","description":"η_F — mittlerer jährlicher AFS63-Frachtrückhalt im RBF durch Filtration. Rechenwert nach Tabelle 1: 0,95.","consumer_worksheets":["A178-13"]},{"ws_code":"A178-13","section_code":"B","symbol":"eta_RR","label_de":"Frachtrückhaltegrad Retentionsraum","label_en":"Retention space load retention","data_type":"number","unit":"-","is_required":true,"enum_values":null,"validation_rules":{"raw":"Rechenwert 0,50"},"clause_reference":"§3.2, §6.2.2.3, Tabelle 1","description":"η_RR — mittlerer jährlicher AFS63-Frachtrückhalt im Retentionsraum / Sedimentationskammer. Rechenwert nach Tabelle 1: 0,50.","consumer_worksheets":["A178-13"]},{"ws_code":"A178-13","section_code":"B","symbol":"eta_RRL","label_de":"Frachtrückhaltegrad RRL","label_en":"RRL load retention","data_type":"number","unit":"-","is_required":false,"enum_values":null,"validation_rules":{"raw":"Rechenwert 0,60"},"clause_reference":"§3.2, §6.2.2.3, Tabelle 1","description":"η_RRL — mittlerer jährlicher AFS63-Frachtrückhalt in der Regenrückhaltelamelle. Rechenwert nach Tabelle 1: 0,60.","consumer_worksheets":["A178-13"]},{"ws_code":"A178-15","section_code":"C","symbol":"eta_RBF_hyd","label_de":"Hydraulischer Wirkungsgrad","label_en":"Hydraulic efficiency","data_type":"number","unit":"-","is_required":true,"enum_values":null,"validation_rules":{"raw":"0..1"},"clause_reference":"§3.2, §6.2.2.3, Gl. (12)","description":"η_RBF,hyd — mittlerer jährlicher hydraulischer Wirkungsgrad des Retentionsbodenfilterbeckens.","consumer_worksheets":["A178-19"]},{"ws_code":"A178-13","section_code":"C","symbol":"b_F","label_de":"Spezifische Filterflächenbelastung","label_en":"Specific filter-area loading","data_type":"number","unit":"kg/(m^2*a)","is_required":true,"enum_values":null,"validation_rules":{"raw":"4 <= b_F <= 7 (= b_krit)"},"clause_reference":"§3.2, §6.2.2.3, Gl. (5)/(6)/(7), Gl. (9)","description":"b_F — mittlere jährliche spezifische AFS63-Filterflächenbelastung. Bemessungsergebnis.","consumer_worksheets":["A178-16"]},{"ws_code":"A178-17","section_code":"B","symbol":"k_f_b","label_de":"Betrieblicher k_f-Wert","label_en":"Operational permeability","data_type":"number","unit":"m/s","is_required":false,"enum_values":null,"validation_rules":{"raw":"k_f,b < 1e-6 deutet auf Kolmation"},"clause_reference":"§3.2, §8.3.2","description":"k_f,b — betrieblicher Durchlässigkeitsbeiwert. Warngrenze <10^-6 m/s (Kolmationshinweis).","consumer_worksheets":null},{"ws_code":"A178-16","section_code":"E","symbol":"nachweis_b_F","label_de":"Nachweis b_F","label_en":"Verification b_F vs b_krit","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"enum: pass|fail|conditional"},"clause_reference":"§6.2.2.3, Gl. (9)","description":"Gate result of b_F ≤ b_krit and b_F ≥ 4 kg/(m²·a). FAIL → Iteration (A178-18).","consumer_worksheets":["A178-19"]},{"ws_code":"A178-16","section_code":"E","symbol":"nachweis_einleitfracht","label_de":"Nachweis Einleitfracht","label_en":"Verification of discharge load","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"enum: pass|fail|conditional"},"clause_reference":"§6.2.2.3, Gl. (10)","description":"Gate result of B_RBFA,ab / A_E,b,a ≤ b_R,e,zul. FAIL → Iteration.","consumer_worksheets":["A178-19"]},{"ws_code":"A178-19","section_code":"F","symbol":"compliance_verdict","label_de":"Konformitätsurteil","label_en":"Compliance verdict","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"compliant","label_de":"konform","label_en":"compliant","order_index":1,"regulation_reference":"methodology"},{"value":"compliant_with_conditions","label_de":"konform mit Auflagen","label_en":"compliant with conditions","order_index":2,"regulation_reference":"methodology"},{"value":"not_compliant","label_de":"nicht konform","label_en":"not compliant","order_index":3,"regulation_reference":"methodology"},{"value":"insufficient_data","label_de":"unzureichende Daten","label_en":"insufficient data","order_index":4,"regulation_reference":"methodology"}],"validation_rules":{"raw":"enum: compliant|compliant_with_conditions|not_compliant|insufficient_data"},"clause_reference":"§6.2, Anhang A","description":"Gesamtkonformität nach Iteration (alle Nachweise + zusätzliche Nachweise).","consumer_worksheets":null},{"ws_code":"A178-07","section_code":"B","symbol":"filter_ueberkornanteil","label_de":"Überkornanteil Filtermaterial","label_en":"Filter material oversize fraction","data_type":"number","unit":"Massen-%","is_required":true,"enum_values":null,"validation_rules":{"raw":"<= 15"},"clause_reference":"§6.1.4.6","description":"Maximaler Überkornanteil im Filtermaterial (TL Gestein-StB 04/07, Kategorie G_F 85).","consumer_worksheets":null},{"ws_code":"A178-07","section_code":"B","symbol":"filter_feinanteil","label_de":"Feinanteil Filtermaterial (<0,063 mm)","label_en":"Filter material fines fraction (<0.063 mm)","data_type":"number","unit":"Massen-%","is_required":true,"enum_values":null,"validation_rules":{"raw":"<= 3"},"clause_reference":"§6.1.4.6","description":"Maximaler Feinanteil (<0,063 mm) im Filtermaterial (TL Gestein-StB 04/07, f_3).","consumer_worksheets":null},{"ws_code":"A178-07","section_code":"B","symbol":"abdichtung_kdb_staerke","label_de":"KDB-Stärke Abdichtung","label_en":"PE liner thickness","data_type":"number","unit":"mm","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 2"},"clause_reference":"§6.1.4.9","description":"Erforderliche Stärke der Kunststoffdichtungsbahnen (KDB) für die Abdichtung.","consumer_worksheets":null},{"ws_code":"A178-07","section_code":"B","symbol":"v_spez_grobstoff","label_de":"Spez. Speichervolumen Grobstoffrückhalt","label_en":"Specific storage volume of coarse-matter pre-stage","data_type":"number","unit":"m^3/ha","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 0.5 (Trennsystem)"},"clause_reference":"§6.2.1.2","description":"Spez. Sammelvolumen des unbelüfteten Grobstoffrückhalts im Trennsystem, bezogen auf A_E,b,a.","consumer_worksheets":null},{"ws_code":"A178-05","section_code":"B.7","symbol":"langzeitsimulation_dauer","label_de":"Dauer der Langzeitsimulation","label_en":"Long-term simulation duration","data_type":"number","unit":"a","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 10"},"clause_reference":"§6.2.2.3","description":"Mindestlänge der Niederschlagsbelastungsreihe für die Kontinuumssimulation.","consumer_worksheets":["A178-12","A178-13","A178-14"]},{"ws_code":"A178-07","section_code":"B","symbol":"pflanzdichte","label_de":"Schilf-Pflanzdichte","label_en":"Reed planting density","data_type":"number","unit":"1/m^2","is_required":false,"enum_values":null,"validation_rules":{"raw":"4..8"},"clause_reference":"§6.1.4.7","description":"Anzahl vorkultivierter Phragmites-communis-Pflanzen je Quadratmeter Bodenfilteroberfläche.","consumer_worksheets":null},{"ws_code":"A178-07","section_code":"B","symbol":"geotextil_zwischen_filter_drane","label_de":"Geotextil zwischen Filterkörper und Dränschicht eingebaut","label_en":"Geotextile installed between filter body and drainage layer","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"must be FALSE"},"clause_reference":"§6.1.4.5, §7.2","description":"Booleanflag: ist ein Geotextil zwischen Filterkörper und Dränschicht eingebaut? Muss FALSE sein.","consumer_worksheets":null},{"ws_code":"A178-17","section_code":"B","symbol":"dauerhafter_einstau","label_de":"Dauerhafter Teileinstau des Filterkörpers im Regelbetrieb","label_en":"Permanent partial ponding of filter body under normal operation","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"must be FALSE"},"clause_reference":"§6.1.4.7, §8.2.3, §8.2.4","description":"Booleanflag: liegt ein dauerhafter Teileinstau des Filterkörpers vor? Muss FALSE sein.","consumer_worksheets":null}],"equations":[{"ws_code":"A178-10","equation_number":"1","formula":"A_F = (B_RBF_zu / b_krit) * eta_B_soll","input_symbols":["B_RBF_zu","b_krit","eta_B_soll"],"output_symbol":"A_F","clause_reference":"§6.2.2.1, Gl. (1)","description":"Vorbemessung Bodenfilteroberfläche"},{"ws_code":"A178-09","equation_number":"2","formula":"B_RBF_zu = SUM_over_i(A_E_b_a_i * b_R_a)","input_symbols":["A_E_b_a_i","b_R_a"],"output_symbol":"B_RBF_zu","clause_reference":"§6.2.2.1, Gl. (2)","description":"Filterzulauffracht im Trennsystem"},{"ws_code":"A178-09","equation_number":"3","formula":"B_RBF_zu = SUM_over_i(A_E_b_a_i * b_R_a * e_0)","input_symbols":["A_E_b_a_i","b_R_a","e_0"],"output_symbol":"B_RBF_zu","clause_reference":"§6.2.2.1, Gl. (3)","description":"Filterzulauffracht im Mischsystem"},{"ws_code":"A178-11","equation_number":"4","formula":"Q_Dr_RBF = q_Dr_RBF * A_F","input_symbols":["q_Dr_RBF","A_F"],"output_symbol":"Q_Dr_RBF","clause_reference":"§6.2.2.1, Gl. (4)","description":"Drosselabfluss"},{"ws_code":"A178-13","equation_number":"5","formula":"b_F = ((VQ_Dr_RBF * eta_F) * C_RBFA_zu * (1 - eta_VS)) / (A_F * 1000)","input_symbols":["VQ_Dr_RBF","eta_F","C_RBFA_zu","eta_VS","A_F"],"output_symbol":"b_F","clause_reference":"§6.2.2.3, Gl. (5)","description":"b_F bei Fangfilterbecken"},{"ws_code":"A178-13","equation_number":"6","formula":"b_F = ((VQ_Dr_RBF * eta_F + VQ_FU * eta_RR) * C_RBFA_zu * (1 - eta_VS)) / (A_F * 1000)","input_symbols":["VQ_Dr_RBF","eta_F","VQ_FU","eta_RR","C_RBFA_zu","eta_VS","A_F"],"output_symbol":"b_F","clause_reference":"§6.2.2.3, Gl. (6)","description":"b_F bei Durchlauffilterbecken"},{"ws_code":"A178-13","equation_number":"7","formula":"b_F = ((VQ_Dr_RBF * eta_F + VQ_FU * eta_RR + VQ_Dr_RRL * eta_RRL) * C_RBFA_zu * (1 - eta_VS)) / (A_F * 1000)","input_symbols":["VQ_Dr_RBF","eta_F","VQ_FU","eta_RR","VQ_Dr_RRL","eta_RRL","C_RBFA_zu","eta_VS","A_F"],"output_symbol":"b_F","clause_reference":"§6.2.2.3, Gl. (7)","description":"b_F mit Regenrückhaltelamelle"},{"ws_code":"A178-12","equation_number":"8","formula":"C_RBFA_zu = (B_RBFA_zu * 1000) / VQ_RBFA_zu","input_symbols":["B_RBFA_zu","VQ_RBFA_zu"],"output_symbol":"C_RBFA_zu","clause_reference":"§6.2.2.3, Gl. (8)","description":"Mittlere Konzentration im Zulauf zur RBFA"},{"ws_code":"A178-16","equation_number":"9","formula":"4 <= b_F <= b_krit = 7   [kg/(m^2*a)]","input_symbols":["b_F","b_krit"],"output_symbol":"—","clause_reference":"§6.2.2.3, Gl. (9)","description":"Zulässige AFS63-Bodenfilteroberflächenbelastung"},{"ws_code":"A178-16","equation_number":"10","formula":"B_RBFA_ab / A_E_b_a <= b_R_e_zul","input_symbols":["B_RBFA_ab","A_E_b_a","b_R_e_zul"],"output_symbol":"—","clause_reference":"§6.2.2.3, Gl. (10)","description":"Spezifische Einleitfracht aus der RBFA"},{"ws_code":"A178-14","equation_number":"11","formula":"B_RBFA_ab = B_VS + B_Dr_RBF + B_FU + B_RRL","input_symbols":["B_VS","B_Dr_RBF","B_FU","B_RRL"],"output_symbol":"B_RBFA_ab","clause_reference":"§6.2.2.3, Gl. (11)","description":"Frachtaustrag aus der RBFA"},{"ws_code":"A178-15","equation_number":"12","formula":"eta_RBF_hyd = VQ_Dr_RBF / VQ_RBF_zu","input_symbols":["VQ_Dr_RBF","VQ_RBF_zu"],"output_symbol":"eta_RBF_hyd","clause_reference":"§6.2.2.3, Gl. (12)","description":"Hydraulischer Wirkungsgrad"},{"ws_code":"A178-15","equation_number":"13","formula":"eta_F = ((C_RBF_zu * VQ_DR_RBF_zu) - (B_RBF_ab * 1000)) / (C_RBF_zu * VQ_RBF_zu)","input_symbols":["C_RBF_zu","VQ_Dr_RBF","B_RBF_ab","VQ_RBF_zu"],"output_symbol":"eta_F","clause_reference":"§6.2.2.3, Gl. (13)","description":"Frachtwirkungsgrad"}],"compliance":[{"ws_code":"A178-01","code":"REQ-01","title_de":"Anwendbarkeit Scope","condition":"manual_check","description":"Anlage fällt in Anwendungsbereich (RBFA für MS/TS/Straße, kein Pilotmaßstab).","clause_reference":"§1.1"},{"ws_code":"A178-01","code":"REQ-02","title_de":"Behandlungsziel definiert","condition":"presence_and_value","description":"Schutzziele und Zielgrößen sind mit den Genehmigungsbehörden geklärt (z. B. AFS63).","clause_reference":"§1.2, §5.1"},{"ws_code":"A178-01","code":"REQ-03","title_de":"Umsetzbarkeit geprüft (Bild 1)","condition":"manual_check_against_bild_1","description":"Prüfung der Umsetzbarkeit gemäß §5 ist vor Planungsauftrag erfolgt.","clause_reference":"§5.1, Bild 1"},{"ws_code":"A178-04","code":"REQ-04","title_de":"Zuflussabschätzung belastbar","condition":"manual_check","description":"Niederschlags-/Misch-/Fremdwasserzuflüsse sind realitätsnah ermittelt.","clause_reference":"§5.2.1, §5.2.2"},{"ws_code":"A178-04","code":"REQ-05","title_de":"Fremdwassermaßnahmen geprüft","condition":"manual_check","description":"Bei Fremdwasserzufluss ist Sanierung erfolgreich; sonst alternierende Beschickung oder Bauabbruch.","clause_reference":"§5.2.2"},{"ws_code":"A178-04","code":"REQ-06","title_de":"Vorhandene Regenbecken einbezogen","condition":"manual_check","description":"Vorhandene Regenbecken im Einzugsgebiet sind in der Planung berücksichtigt.","clause_reference":"§5.2.3"},{"ws_code":"A178-04","code":"REQ-07","title_de":"Feststoffeintrag plausibel","condition":"feststoffeintrag_alarm == false","description":"AFS63-Eintrag ≤ 1.000 kg/(ha·a) typisch; höhere Werte erfordern Sonderprüfung.","clause_reference":"§5.2.4"},{"ws_code":"A178-04","code":"REQ-08","title_de":"Sonderflächen evaluiert","condition":"manual_check","description":"Niederschlagsabflüsse von Sonderflächen (Biogas, Substratlager) sind im Einzelfall geprüft.","clause_reference":"§5.2.5"},{"ws_code":"A178-12","code":"REQ-09","title_de":"Vorstufe Mischsystem nach ATV-A 128","condition":"if system_type==misch: e_0 <= 55 AND n_RBF >= 10","description":"Im Mischsystem: Vorstufe ist nach ATV-A 128 bemessen, e_0 ≤ 55 %, n ≥ 10/a.","clause_reference":"§6.2.1.1"},{"ws_code":"A178-12","code":"REQ-10","title_de":"Vorstufe Trennsystem als Grobstoffrückhalt","condition":"manual_check","description":"Im Trennsystem: unbelüfteter Grobstoffrückhalt mit V_spez ≥ 0,5 m³/ha A_E,b,a.","clause_reference":"§6.2.1.2"},{"ws_code":"A178-12","code":"REQ-11","title_de":"Vorstufe Straßenentwässerung","condition":"conditional_check","description":"Bei Straßenentwässerung außerhalb WSG: wie Trennsystem; innerhalb WSG: zusätzl. Leichtflüssigkeitsfang nach RiStWag.","clause_reference":"§6.2.1.3"},{"ws_code":"A178-12","code":"REQ-12","title_de":"Filterkörperhöhe ausreichend","condition":"conditional_threshold","description":"h_FK ≥ 0,75 m (Mischsystem) bzw. ≥ 0,50 m (Trenn/Straße) im konsolidierten Zustand.","clause_reference":"§6.1.4.5"},{"ws_code":"A178-12","code":"REQ-13","title_de":"Filtermaterial-Anforderungen","condition":"multi_threshold","description":"Korngruppe 0/2 mm, U < 5, Feinanteil ≤ 3 M%, Überkorn ≤ 15 M%, CaCO3 ≥ 20 M%.","clause_reference":"§6.1.4.6"},{"ws_code":"A178-12","code":"REQ-14","title_de":"Drosselabflussspende begrenzt","condition":"q_Dr_RBF <= 0.05","description":"q_Dr,RBF ≤ 0,05 l/(s·m²) bei Volleinstau.","clause_reference":"§6.1.4.10"},{"ws_code":"A178-09","code":"REQ-15","title_de":"Einstauhöhe innerhalb Bereich","condition":"range_check","description":"h_RR zwischen 0,3 m und 2,0 m; bei Straße ≥ 0,5 m.","clause_reference":"§6.1.4.3, §6.2.2.2"},{"ws_code":"A178-09","code":"REQ-16","title_de":"Vereinfachte Bemessung Straße","condition":"conditional_simple_method","description":"Straße ohne Sonderziele: A_F = 100 m²/ha A_E,b,a; h_RR ≥ 0,5 m; kein Nachweis erforderlich.","clause_reference":"§6.2.2.2"},{"ws_code":"A178-09","code":"REQ-17","title_de":"Vorbemessung A_F (Gl. 1)","condition":"equation_1_evaluated","description":"A_F = B_RBF,zu / b_krit · η_B,soll wurde berechnet.","clause_reference":"§6.2.2.1, Gl. (1)"},{"ws_code":"A178-09","code":"REQ-18","title_de":"Trenn >1000 mm/a Mindestfläche","condition":"conditional_threshold","description":"Bei Trenn und h_N,a,m > 1.000 mm/a: A_F ≥ 100 m²/ha A_E,b,a.","clause_reference":"§6.2.2.1"},{"ws_code":"A178-16","code":"REQ-19","title_de":"Nachweis Belastungsgrenzen (Gl. 9)","condition":"4 <= b_F AND b_F <= 7","description":"4 kg/(m²·a) ≤ b_F ≤ b_krit = 7 kg/(m²·a) — sowohl Unterlast als auch Überlast.","clause_reference":"§6.2.2.3, Gl. (9)"},{"ws_code":"A178-16","code":"REQ-20","title_de":"Nachweis Einleitfracht (Gl. 10)","condition":"B_RBFA_ab / A_E_b_a <= b_R_e_zul","description":"B_RBFA,ab / A_E,b,a ≤ b_R,e,zul.","clause_reference":"§6.2.2.3, Gl. (10)"},{"ws_code":"A178-16","code":"REQ-21","title_de":"Einstaudauer Mischsystem","condition":"if system_type==misch: t_RR_E_n1 <= 48","description":"Im Mischsystem: t_RR,E,n=1 ≤ 48 h.","clause_reference":"§6.2.2.3c"},{"ws_code":"A178-16","code":"REQ-22","title_de":"Beschickungshäufigkeit Mindestmaß","condition":"n_RBF >= 10","description":"n_RBF ≥ 10/a im langjährigen Mittel.","clause_reference":"§6.2.2.3c, §6.2.1.1"},{"ws_code":"A178-12","code":"REQ-23","title_de":"Langzeitsimulation ≥ 10 Jahre","condition":"manual_check","description":"Nachweis basiert auf Kontinuumssimulation mit ≥ 10 Jahren Niederschlagsbelastung.","clause_reference":"§6.2.2.3"},{"ws_code":"A178-18","code":"REQ-24","title_de":"Iteration bei Nichteinhalten","condition":"manual_check","description":"Bei nicht erfüllten Zielgrößen: Iteration A_F und/oder h_RR variieren bis alle Nachweise erfüllt.","clause_reference":"§6.2.2.4"},{"ws_code":"A178-12","code":"REQ-25","title_de":"Abdichtung mit KDB","condition":"manual_check","description":"Abdichtung mit Kunststoffdichtungsbahnen, Stärke ≥ 2 mm, beidseitig durch Geotextil geschützt.","clause_reference":"§6.1.4.9, §7.1"},{"ws_code":"A178-12","code":"REQ-26","title_de":"Geotextil zwischen Filter/Dräne verboten","condition":"manual_check","description":"Zwischen Filterkörper und Dränschicht darf kein Geotextil eingebaut werden (Kolmationsgefahr).","clause_reference":"§6.1.4.5, §7.2"},{"ws_code":"A178-12","code":"REQ-27","title_de":"Schilfbepflanzung Etablierungsphase","condition":"manual_check","description":"Vorkultivierte Phragmites communis mit 4-8 Pflanzen/m² und einer Vegetationsperiode Fertigstellungspflege.","clause_reference":"§6.1.4.7, §7.4, §8.1"},{"ws_code":"A178-18","code":"REQ-28","title_de":"Betriebliche Untersuchungen","condition":"manual_check","description":"Wasserstandsmessungen, jährliche Auswertung, 5-jährliche Depotuntersuchungen.","clause_reference":"§8.3.1-8.3.3"}]}$p3c_json$::jsonb;
  v_std uuid;
BEGIN
  -- 1. standard (UPSERT by code)
  INSERT INTO standards (code, title_de, title_en, version)
  SELECT v_data->'standard'->>'code', v_data->'standard'->>'title_de',
         v_data->'standard'->>'title_en', v_data->'standard'->>'version'
  ON CONFLICT (code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, version = excluded.version;
  SELECT id INTO v_std FROM standards WHERE code = v_data->'standard'->>'code';

  -- 2. worksheet templates (UPSERT by standard_id+code)
  INSERT INTO worksheet_templates (standard_id, code, title_de, title_en, phase, archetype, order_index, description)
  SELECT v_std, w->>'code', w->>'title_de', w->>'title_en',
         (w->>'phase')::int, w->>'archetype', (w->>'order_index')::int, w->>'description'
  FROM jsonb_array_elements(v_data->'worksheets') AS w
  ON CONFLICT (standard_id, code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, phase = excluded.phase,
        archetype = excluded.archetype, order_index = excluded.order_index, description = excluded.description;

  -- 3. sections: null fields.section_id, wipe + reinsert (no unique constraint on code), resolve parents
  UPDATE fields SET section_id = NULL
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);
  DELETE FROM worksheet_sections
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);

  INSERT INTO worksheet_sections (worksheet_template_id, code, title_de, order_index)
  SELECT wt.id, s->>'code', s->>'title_de', (s->>'order_index')::int
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code';

  UPDATE worksheet_sections AS child
     SET parent_section_id = parent.id
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code'
  JOIN worksheet_sections parent ON parent.worksheet_template_id = wt.id AND parent.code = s->>'parent_code'
  WHERE s->>'parent_code' IS NOT NULL
    AND child.worksheet_template_id = wt.id
    AND child.code = s->>'code';

  -- 4. fields (UPSERT by worksheet_template_id+symbol; verification_status NOT touched)
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit,
                      is_required, enum_values, validation_rules, clause_reference, description, consumer_worksheets)
  SELECT wt.id,
         (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = wt.id AND ws.code = f->>'section_code' LIMIT 1),
         f->>'symbol', f->>'label_de', f->>'label_en', f->>'data_type', f->>'unit',
         (f->>'is_required')::boolean,
         CASE WHEN jsonb_typeof(f->'enum_values') = 'array' THEN f->'enum_values' ELSE NULL END,
         CASE WHEN jsonb_typeof(f->'validation_rules') = 'object' THEN f->'validation_rules' ELSE NULL END,
         f->>'clause_reference', f->>'description',
         CASE WHEN jsonb_typeof(f->'consumer_worksheets') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(f->'consumer_worksheets')) ELSE NULL END
  FROM jsonb_array_elements(v_data->'fields') AS f
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = f->>'ws_code'
  ON CONFLICT (worksheet_template_id, symbol) DO UPDATE
    SET section_id = excluded.section_id, label_de = excluded.label_de, label_en = excluded.label_en,
        data_type = excluded.data_type, unit = excluded.unit, is_required = excluded.is_required,
        enum_values = excluded.enum_values, validation_rules = excluded.validation_rules,
        clause_reference = excluded.clause_reference, description = excluded.description,
        consumer_worksheets = excluded.consumer_worksheets;

  -- 5. equations (UPSERT by worksheet_template_id+equation_number; verification_status preserved)
  INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, clause_reference, description)
  SELECT wt.id, e->>'equation_number', e->>'formula',
         CASE WHEN jsonb_typeof(e->'input_symbols') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(e->'input_symbols')) ELSE NULL END,
         e->>'output_symbol', e->>'clause_reference', e->>'description'
  FROM jsonb_array_elements(v_data->'equations') AS e
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = e->>'ws_code'
  ON CONFLICT (worksheet_template_id, equation_number) DO UPDATE
    SET formula = excluded.formula, input_symbols = excluded.input_symbols, output_symbol = excluded.output_symbol,
        clause_reference = excluded.clause_reference, description = excluded.description;

  -- 6. compliance requirements (UPSERT by worksheet_template_id+code)
  INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, condition, description, clause_reference, severity)
  SELECT wt.id, c->>'code', c->>'title_de', c->>'condition', c->>'description', c->>'clause_reference', 'block'
  FROM jsonb_array_elements(v_data->'compliance') AS c
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = c->>'ws_code'
  ON CONFLICT (worksheet_template_id, code) DO UPDATE
    SET title_de = excluded.title_de, condition = excluded.condition, description = excluded.description,
        clause_reference = excluded.clause_reference, severity = excluded.severity;
END
$p3c_do$;
